import{_ as i,o as a,c as t,a2 as r}from"./chunks/framework.DQhM5RF8.js";const h=JSON.parse('{"title":"Server Rules & Guidelines","description":"","frontmatter":{},"headers":[],"relativePath":"guide/rules.md","filePath":"guide/rules.md"}'),n={name:"guide/rules.md"};function o(s,e,l,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="server-rules-guidelines" tabindex="-1">Server Rules &amp; Guidelines <a class="header-anchor" href="#server-rules-guidelines" aria-label="Permalink to &quot;Server Rules &amp; Guidelines&quot;">​</a></h1><p>To ensure a fair, competitive, and enjoyable environment for everyone on LlamaCraft, all players must abide by the following server regulations.</p><hr><h2 id="_1-respect-and-fair-play" tabindex="-1">1. Respect and Fair Play <a class="header-anchor" href="#_1-respect-and-fair-play" aria-label="Permalink to &quot;1. Respect and Fair Play&quot;">​</a></h2><ul><li>Harassment, hate speech, slurs, threats, and discrimination are strictly prohibited.</li><li>Do not bypass server chat filters, mute punishments, or ban enforcements using alternate accounts.</li><li>Respect server moderators and staff decisions. Appeals can be submitted via Discord ticket.</li></ul><hr><h2 id="_2-fair-competition-client-integrity" tabindex="-1">2. Fair Competition &amp; Client Integrity <a class="header-anchor" href="#_2-fair-competition-client-integrity" aria-label="Permalink to &quot;2. Fair Competition &amp; Client Integrity&quot;">​</a></h2><ul><li><strong>Allowed Mods</strong>: Optimization mods (Sodium, Lithium, Iris, OptiFine), HUD information mods (ArmorStatus, Minimap without entity radars), Simple Voice Chat client mod.</li><li><strong>Prohibited Modifications</strong>: Any client hacks, auto-clickers, macros exceeding human CPS limits, baritone automation, X-Ray texture packs, or reach/hitbox modifications.</li><li>Unfair advantages result in an immediate automatic ban by our anti-cheat engine.</li></ul><hr><h2 id="_3-land-claims-raiding-mechanics" tabindex="-1">3. Land Claims &amp; Raiding Mechanics <a class="header-anchor" href="#_3-land-claims-raiding-mechanics" aria-label="Permalink to &quot;3. Land Claims &amp; Raiding Mechanics&quot;">​</a></h2><ul><li>Players may protect their bases using the land claim tool (<code>/claim</code>).</li><li>During designated <strong>Siege Windows</strong>, claims can be contested under standard server siege rules.</li><li>Do not exploit chunk boundaries, ghost blocks, or combat-logging glitches during PVP encounters.</li><li>Intentional lag machines, extreme redstone clock spam, or server-crashing item drops will be permanently purged.</li></ul><hr><h2 id="_4-voice-chat-conduct" tabindex="-1">4. Voice Chat Conduct <a class="header-anchor" href="#_4-voice-chat-conduct" aria-label="Permalink to &quot;4. Voice Chat Conduct&quot;">​</a></h2><ul><li>No ear-rape, high-gain noise blasting, or screaming into proximity voice.</li><li>Soundboard clips must not be spammed repeatedly in crowded public areas.</li><li>Respect player muting preferences.</li></ul>',14)])])}const p=i(n,[["render",o]]);export{h as __pageData,p as default};
